
const WORDS=[{"id": 0, "w": "养", "p": "yǎng", "t": "动词", "m": "nuôi, trồng và chăm sóc; nuôi dưỡng", "coll": "养花、养鱼", "s": "爷爷退休以后，喜欢在院子里养一些容易照顾的花。"}, {"id": 1, "w": "除非", "p": "chúfēi", "t": "连词", "m": "trừ phi, chỉ khi; nếu không (thường đi với 否则)", "coll": "除非……否则……、除非有事", "s": "除非下大雨，否则我们明天一定按计划去参观花展。"}, {"id": 2, "w": "奋斗", "p": "fèndòu", "t": "动词", "m": "phấn đấu, nỗ lực bền bỉ", "coll": "努力奋斗、为理想奋斗", "s": "为了实现自己的理想，她一直努力奋斗，从来没有轻易放弃。"}, {"id": 3, "w": "乐趣", "p": "lèqù", "t": "名词", "m": "niềm vui, sự thú vị", "coll": "生活乐趣、找到乐趣", "s": "通过照顾花草，他慢慢体会到了园艺活动的乐趣。"}, {"id": 4, "w": "在乎", "p": "zàihu", "t": "动词", "m": "quan tâm, để tâm, coi trọng", "coll": "在乎结果、不在乎得失", "s": "她并不在乎这次比赛能不能获奖，只希望自己有所进步。"}, {"id": 5, "w": "朵", "p": "duǒ", "t": "量词", "m": "bông, đóa (lượng từ cho hoa, mây)", "coll": "一朵花、一朵云", "s": "小女孩指着窗边刚刚开放的一朵花，高兴地叫了起来。"}, {"id": 6, "w": "剪刀", "p": "jiǎndāo", "t": "名词", "m": "cái kéo", "coll": "一把剪刀、用剪刀剪纸", "s": "老师拿出一把剪刀，给同学们示范怎样剪出漂亮的图案。"}, {"id": 7, "w": "捡", "p": "jiǎn", "t": "动词", "m": "nhặt, nhặt lên", "coll": "捡起来、捡到东西", "s": "看到地上有一个空瓶子，他弯下腰，把它捡了起来。"}, {"id": 8, "w": "装饰", "p": "zhuāngshì", "t": "动词 / 名词", "m": "trang trí; đồ trang trí", "coll": "装饰房间、节日装饰", "s": "为了迎接节日，大家用鲜花和彩纸装饰了教室。"}, {"id": 9, "w": "结合", "p": "jiéhé", "t": "动词", "m": "kết hợp", "coll": "结合实际、理论结合实践", "s": "学习的时候，我们应该把书本知识与实际生活结合起来。"}, {"id": 10, "w": "暴雨", "p": "bàoyǔ", "t": "名词", "m": "mưa lớn dữ dội, mưa xối xả", "coll": "一场暴雨、狂风暴雨", "s": "一场暴雨过后，院子里到处都是落叶。"}, {"id": 11, "w": "紧急", "p": "jǐnjí", "t": "形容词", "m": "khẩn cấp, cấp bách", "coll": "紧急情况、紧急处理", "s": "如果遇到紧急情况，请按照工作人员的指示有序离开现场。"}, {"id": 12, "w": "劳驾", "p": "láo jià", "t": "动词 / 叹词", "m": "làm phiền, phiền anh/chị (lời nhờ giúp lịch sự)", "coll": "劳驾让一让、劳驾帮忙", "s": "劳驾，请问去植物园的公交车应该在哪一站下车？"}, {"id": 13, "w": "抢救", "p": "qiǎngjiù", "t": "动词", "m": "cứu chữa khẩn cấp, cứu vãn kịp thời", "coll": "抢救伤员、抢救资料", "s": "洪水过后，工作人员立即抢救被水浸湿的珍贵资料。"}, {"id": 14, "w": "腰", "p": "yāo", "t": "名词", "m": "eo, thắt lưng", "coll": "弯腰、腰部", "s": "为了看清这朵小花，他弯下腰，仔细观察了一会儿。"}, {"id": 15, "w": "直", "p": "zhí", "t": "副词 / 形容词", "m": "thẳng; liên tục, không ngừng", "coll": "一条直线、热汗直流", "s": "天气太热，他搬了几盆花以后，已经累得汗水直流。"}, {"id": 16, "w": "不然", "p": "bùrán", "t": "连词", "m": "nếu không thì, bằng không", "coll": "不然就、不然的话", "s": "出门以前记得把窗户关好，不然下雨时屋里会进水。"}, {"id": 17, "w": "回报", "p": "huíbào", "t": "动词 / 名词", "m": "đáp lại, đền đáp; sự đền đáp, lợi ích thu được", "coll": "得到回报、回报社会", "s": "经过长期的努力，他的付出终于得到了回报。"}, {"id": 18, "w": "真理", "p": "zhēnlǐ", "t": "名词", "m": "chân lý, lẽ đúng đắn", "coll": "追求真理、检验真理", "s": "面对新的观点，我们应该认真思考，通过实践检验它是否符合真理。"}, {"id": 19, "w": "浇", "p": "jiāo", "t": "动词", "m": "tưới, đổ nước lên", "coll": "浇花、给植物浇水", "s": "每天早上，她都会到阳台上给花浇水。"}, {"id": 20, "w": "潮湿", "p": "cháoshī", "t": "形容词", "m": "ẩm, ẩm ướt", "coll": "空气潮湿、潮湿的房间", "s": "连续下了几天雨，房间里的空气变得十分潮湿。"}, {"id": 21, "w": "施肥", "p": "shī féi", "t": "动宾短语", "m": "bón phân", "coll": "给花施肥、定期施肥", "s": "这本园艺书详细介绍了给花施肥的方法。"}, {"id": 22, "w": "熟练", "p": "shúliàn", "t": "形容词", "m": "thành thạo, thuần thục", "coll": "动作熟练、熟练操作", "s": "经过一段时间的练习，她已经能够熟练地使用这台机器。"}, {"id": 23, "w": "应付", "p": "yìngfu", "t": "动词", "m": "ứng phó, đối phó; làm qua loa", "coll": "应付困难、应付任务", "s": "面对突然出现的问题，他冷静地想办法，终于应付了过去。"}, {"id": 24, "w": "鲜艳", "p": "xiānyàn", "t": "形容词", "m": "rực rỡ, tươi sáng (màu sắc)", "coll": "颜色鲜艳、鲜艳的花朵", "s": "春天到了，公园里开满了颜色鲜艳的花。"}, {"id": 25, "w": "自豪", "p": "zìháo", "t": "形容词", "m": "tự hào", "coll": "感到自豪、十分自豪", "s": "看到自己种的花终于开放了，他感到十分自豪。"}, {"id": 26, "w": "吹", "p": "chuī", "t": "动词", "m": "thổi; khoác lác, nói quá", "coll": "吹风、吹牛", "s": "他总爱吹牛，把自己说得无所不能，大家却不太相信他。"}, {"id": 27, "w": "爱心", "p": "àixīn", "t": "名词", "m": "lòng yêu thương, lòng nhân ái", "coll": "富有爱心、献爱心", "s": "这位老师很有爱心，经常利用休息时间帮助有困难的学生。"}, {"id": 28, "w": "分享", "p": "fēnxiǎng", "t": "动词", "m": "chia sẻ, cùng hưởng", "coll": "分享经验、分享快乐", "s": "活动结束以后，同学们坐在一起，分享各自的收获。"}, {"id": 29, "w": "昙花", "p": "tánhuā", "t": "名词", "m": "hoa quỳnh", "coll": "一盆昙花、昙花开放", "s": "奶奶养了一盆昙花，每天都会仔细观察它的变化。"}, {"id": 30, "w": "庆祝", "p": "qìngzhù", "t": "动词", "m": "ăn mừng, chào mừng, tổ chức mừng", "coll": "庆祝节日、庆祝成功", "s": "为了庆祝项目顺利完成，大家决定一起吃顿饭。"}, {"id": 31, "w": "保留", "p": "bǎoliú", "t": "动词", "m": "giữ lại, bảo lưu", "coll": "保留意见、保留资料", "s": "整理旧物的时候，她保留了几封很有纪念意义的信。"}, {"id": 32, "w": "菊花", "p": "júhuā", "t": "名词", "m": "hoa cúc", "coll": "一盆菊花、观赏菊花", "s": "花展上摆着各种颜色的菊花，吸引了不少游客。"}, {"id": 33, "w": "砸", "p": "zá", "t": "动词", "m": "đập, nện; rơi đập vào làm hỏng", "coll": "砸坏、砸到", "s": "一块石头从山坡上滚下来，砸坏了停在路边的一辆自行车。"}, {"id": 34, "w": "悲伤", "p": "bēishāng", "t": "形容词", "m": "buồn đau, đau buồn", "coll": "感到悲伤、悲伤的消息", "s": "听到这个令人悲伤的消息，大家都沉默了，一时不知道该说什么。"}, {"id": 35, "w": "反正", "p": "fǎnzhèng", "t": "副词", "m": "dù sao, đằng nào thì", "coll": "反正都一样、反正有时间", "s": "反正今天下午没有别的安排，我们不如一起去公园赏花吧。"}, {"id": 36, "w": "热爱", "p": "rè'ài", "t": "动词", "m": "yêu tha thiết, yêu sâu sắc", "coll": "热爱生活、热爱自然", "s": "她热爱大自然，总愿意在周末到郊外走一走。"}];
